<?php declare(strict_types=1);require_once __DIR__.'/includes/functions.php';if(currentUser())redirect('index.php');$error='';if(post()){verifyCsrf();$name=clean('full_name',150);$email=emailField('email');$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirm']??'');$username=mb_strtolower(trim((string)($_POST['username']??'')));if(mb_strlen($name)<2||!$email||!preg_match('/^[a-z0-9._-]{3,80}$/',$username)||!validPassword($pass)||$pass!==$confirm)$error='Use a valid name, username (3–80 letters/numbers), matching passwords, and a password of at least 12 characters containing a letter and a number.';else{try{$s=db()->prepare('INSERT INTO users(username,full_name,email,password_hash,role,email_verified) VALUES(?,?,?,?,\'user\',0)');$s->execute([$username,$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('success','Account created. An administrator must verify your email before you can interact with content.');redirect('login.php');}catch(PDOException $x){error_log($x->getMessage());$error='That username or email address is already registered.';}}}$pageTitle='Create account';require __DIR__.'/includes/header.php';?><div class="form-shell"><p class="eyebrow">Join the community</p><h1>Create your account</h1><?php if($error):?><div class="flash error" style="position:static;margin:12px 0"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="field"><label>Full name</label><input name="full_name" maxlength="150" required></div><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._-]{3,80}" maxlength="80" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" minlength="12" required></div><div class="field"><label>Confirm password</label><input type="password" name="password_confirm" minlength="12" required></div><button class="btn primary">Create account</button></form></div><?php require __DIR__.'/includes/footer.php';
